// game/street-items.ts
function polygon(ctx, points, fill, edge) {
  ctx.beginPath();
  ctx.moveTo(...points[0]);
  for (const point of points.slice(1)) ctx.lineTo(...point);
  ctx.closePath();
  ctx.fillStyle = fill;
  ctx.fill();
  if (edge) {
    ctx.strokeStyle = edge;
    ctx.stroke();
  }
}
function oval(ctx, x, y, rx, ry2, color2) {
  ctx.fillStyle = color2;
  ctx.beginPath();
  ctx.ellipse(x, y, rx, ry2, 0, 0, 2 * deterministicMath.PI);
  ctx.fill();
}
function gradient2(ctx, x, y, dx, dy, from, to) {
  const paint2 = ctx.createLinearGradient(x, y, x + dx, y + dy);
  paint2.addColorStop(0, from);
  paint2.addColorStop(1, to);
  return paint2;
}
function round2(ctx, x, y, w, h, radius, color2) {
  ctx.fillStyle = color2;
  ctx.beginPath();
  ctx.roundRect(x, y, w, h, radius);
  ctx.fill();
}
function paint(key, width, height, draw) {
  game.paint(key, width * 2, height * 2, (ctx) => {
    ctx.scale(2, 2);
    ctx.lineJoin = "round";
    ctx.lineCap = "round";
    ctx.lineWidth = 0.95;
    draw(ctx);
  });
}
