// game/touch-feedback.ts
var preference = "touch-vibration";
function vibrationSupported() {
  return typeof navigator !== "undefined" && typeof navigator.vibrate === "function";
}
function vibrationEnabled() {
  return game.save.read(preference, true);
}
function switchVibration() {
  const enabled = !vibrationEnabled();
  game.save.write(preference, enabled);
  if (enabled) vibrate(16);
}
function vibrate(milliseconds) {
  if (vibrationSupported() && vibrationEnabled()) navigator.vibrate(milliseconds);
}

// game/viewport-texture.ts
var ViewportTexture = class {
  constructor(id2, z, layer = "hud") {
    this.id = id2;
    this.z = z;
    this.layer = layer;
  }
  texture;
  get current() {
    const { width, height } = game.screen;
    if (this.texture?.width === width && this.texture.height === height) return this.texture;
    this.texture?.destroy();
    this.texture = game.texture.create({ id: this.id, layer: this.layer, width, height, x: width / 2, y: height / 2 });
    this.texture.handle.z = this.z;
    return this.texture;
  }
};

