    this.banner.fill([{ x: 4, y: 6 }, { x: 390, y: 6 }, { x: 376, y: 33 }, { x: 0, y: 33 }], "#160e29", 0.94);
    this.banner.line(9, 7, 379, 7, 2, STAGES[index].accent, 0.77);
