    const revealing = intro > 1.35 && c.messageTime <= 0;
    this.banner.handle.visible = revealing;
    this.banner.handle.alpha = revealing ? deterministicMath.min(1, (intro - 1.35) * 4) : 0;
    this.message.y = boss ? 112 : 96;
    this.message.text = revealing ? STAGES[index].title : c.messageTime > 0 ? c.message : "";
