var Opening = {
  name: "opening",
  enter() {
    backdrop(0);
    const next = type("", 320, 62, 36, GOLD, "center");
    next.shadow = { color: "#66295d", x: 2, y: 3 };
    const line1 = type("", 320, 230, 16, PAPER2, "center", 14, "sans");
    const line2 = type("", 320, 254, 16, PAPER2, "center", 14, "sans");
    const motif = game.texture.create({ layer: "hud", id: "story-frame" });
    motif.handle.z = 4;
    motif.fill([
      { x: 201, y: 104 },
      { x: 433, y: 104 },
      { x: 451, y: 203 },
      { x: 189, y: 203 }
    ], "#352346", 0.68);
    motif.line(211, 104, 424, 104, 1, "#d46db1", 0.65);
    motif.line(200, 203, 441, 203, 1, "#d46db1", 0.65);
    const image = game.spawn({ texture: "potion", x: 320, y: 153, width: 65, height: 82, layer: "hud", z: 5 });
    const progress = game.texture.create({ layer: "hud", id: "story-progress" });
    progress.handle.z = 16;
    let card = 0, timer = 0, elapsed = 0;
    const advance = () => {
      if (card >= PROLOGUE.length) {
        game.scenes.go("play");
        return;
      }
      const p = PROLOGUE[card++];
      next.text = p.card;
      next.color = p.color;
      line1.text = p.lines[0];
      line2.text = p.icon === "oven" && runFighter !== DEFAULT_FIGHTER ? runFighter.name + " took that personally." : p.lines[1];
      image.setTexture(
        p.icon === "hero" ? runFighter.art : p.icon,
        p.icon === "hero" && runFighter === DEFAULT_FIGHTER ? 21 : 0
      );
      image.width = p.width;
      image.height = p.height;
      timer = 4.1;
    };
    advance();
    footer(touchMode() ? "Tap to continue" : "Enter / A  Continue     Esc / B  Skip");
    game.step("prologue", (dt) => {
      timer -= dt;
      elapsed += dt;
      const fade = deterministicMath.min(1, (4.1 - timer) * 5);
      image.alpha = fade;
      image.y = 153 + (1 - fade) * 12 + deterministicMath.sin(elapsed * 4) * 3;
      image.rot = deterministicMath.sin(elapsed * 2.3) * 0.025;
      progress.clear();
      for (let i = 0; i < PROLOGUE.length; i++) progress.rect(291 + 20 * i, 291, 16, 2, i < card ? HOT : "#675273");
      toggleMute();
      if (elapsed > 0.2 && game.controls.justPressed("back")) game.scenes.go("play");
      else if (timer <= 0 || elapsed > 0.2 && (game.controls.justPressed("accept") || game.input.pointer?.pressed)) advance();
    });
  }
};
